public static async Task<T> RetryAsync<T>(
    Func<CancellationToken, Task<T>> operation,
    int maximumAttempts,
    CancellationToken cancellationToken)
{
    for (int attempt = 1; attempt <= maximumAttempts; attempt++)
    {
        try
        {
            return await operation(cancellationToken);
        }
        catch (TimeoutException) when (attempt < maximumAttempts)
        {
            int jitterMilliseconds = Random.Shared.Next(0, 100);
            double exponentialMilliseconds = 100 * Math.Pow(2, attempt - 1);
            TimeSpan delay = TimeSpan.FromMilliseconds(
                exponentialMilliseconds + jitterMilliseconds);
            await Task.Delay(delay, cancellationToken);
        }
    }

    throw new InvalidOperationException("The retry loop ended unexpectedly.");
}

